SERVICE_CONTENT = 'from __future__ import annotations\n\n"""\nBÀI 13B-11.15.2.4.6\nBộ quy tắc/công thức Mầm non theo file:\n    Bieu pho cap GDMN(1).xlsx\n\nNguyên tắc:\n- Python tính trực tiếp; không phụ thuộc Excel recalculation.\n- Mẫu số trống hoặc <= 0 -> để trống.\n- Tỷ số GV/lớp, phòng/lớp KHÔNG nhân 100.\n- Tỷ lệ % nhân 100.\n- Không tự suy đoán dữ liệu đầu vào chưa có.\n"""\n\nfrom typing import Any\n\n\nREFERENCE_SHA256 = "c5d2a4ab84197d221de8ffdcc8b8f7b635cd469cadf347bf29471541e81fb89e"\n\nFORMULA_CONTRACT = {\n    "MN01_TE": {\n        "mobilization": "attending / required * 100",\n        "two_sessions": "two_sessions / attending * 100",\n        "completion": "completed / completion_denominator * 100",\n        "disability_access": "disabled_access / disabled_can_learn * 100",\n    },\n    "MN01_TC_DK": {\n        "classes_total": "single_classes + mixed_classes",\n        "mobilization": "attending / required * 100",\n        "completion": "completed / attending * 100",\n        "disability_access": "disabled_access / disabled_can_learn * 100",\n    },\n    "MN01_GV": {\n        "teacher_class_ratio": "teachers / classes",\n        "qualified_rate": "(qualified + above_qualified) / teachers * 100",\n        "professional_standard_rate": "professional_standard / teachers * 100",\n    },\n    "MN01_CSVC": {\n        "room_class_ratio": "classrooms / classes",\n    },\n    "FINANCE": {\n        "five_year_average": "(y1+y2+y3+y4+y5)/5",\n    },\n}\n\n\ndef safe_number(value: Any) -> float | None:\n    if value in (None, ""):\n        return None\n\n    if isinstance(value, bool):\n        return float(int(value))\n\n    if isinstance(value, (int, float)):\n        return float(value)\n\n    text = str(value).strip()\n\n    if not text:\n        return None\n\n    # Không cố parse công thức Excel/text hướng dẫn.\n    if text.startswith("="):\n        return None\n\n    text = text.replace(" ", "")\n\n    # Hỗ trợ dữ liệu hiển thị VN: 1.234,56 / 12,5.\n    if "," in text and "." in text:\n        if text.rfind(",") > text.rfind("."):\n            text = text.replace(".", "").replace(",", ".")\n        else:\n            text = text.replace(",", "")\n    elif "," in text:\n        text = text.replace(",", ".")\n\n    try:\n        return float(text)\n    except (TypeError, ValueError):\n        return None\n\n\ndef safe_percent(\n    numerator: Any,\n    denominator: Any,\n) -> float | None:\n    n = safe_number(numerator)\n    d = safe_number(denominator)\n\n    if n is None or d is None or d <= 0:\n        return None\n\n    return round(\n        n * 100.0 / d,\n        2,\n    )\n\n\ndef safe_ratio(\n    numerator: Any,\n    denominator: Any,\n) -> float | None:\n    n = safe_number(numerator)\n    d = safe_number(denominator)\n\n    if n is None or d is None or d <= 0:\n        return None\n\n    return round(\n        n / d,\n        2,\n    )\n\n\ndef compatible_can_learn(\n    disability_can_learn: Any,\n    disability_access_education: Any,\n) -> bool:\n    """\n    Tương thích dữ liệu cũ, chỉ dùng trong báo cáo:\n    - True  -> Có\n    - False -> Không (ưu tiên tuyệt đối)\n    - None + access=True -> suy ra Có\n    """\n    if disability_can_learn is True:\n        return True\n\n    if disability_can_learn is False:\n        return False\n\n    return disability_access_education is True\n\n\ndef _cell(ws: Any, ref: str) -> Any:\n    return ws[ref].value\n\n\ndef _set(ws: Any, ref: str, value: Any) -> None:\n    ws[ref] = value\n\n\ndef _sheet(\n    workbook: Any,\n    *names: str,\n) -> Any | None:\n    for name in names:\n        if name in workbook.sheetnames:\n            return workbook[name]\n\n    return None\n\n\ndef _apply_new_te(\n    ws: Any,\n) -> None:\n    # File người dùng gửi:\n    # F:L = tuổi 0..6, M = tổng 0..5.\n    age_cols = (\n        "F", "G", "H", "I", "J", "K", "L",\n    )\n\n    for col in age_cols:\n        _set(\n            ws,\n            f"{col}16",\n            safe_percent(\n                _cell(ws, f"{col}13"),\n                _cell(ws, f"{col}12"),\n            ),\n        )\n\n        _set(\n            ws,\n            f"{col}22",\n            safe_percent(\n                _cell(ws, f"{col}21"),\n                _cell(ws, f"{col}13"),\n            ),\n        )\n\n        _set(\n            ws,\n            f"{col}28",\n            safe_percent(\n                _cell(ws, f"{col}27"),\n                _cell(ws, f"{col}26"),\n            ),\n        )\n\n    # Tổng 0-5, không cộng cột tuổi 6.\n    _set(\n        ws,\n        "M16",\n        safe_percent(\n            _cell(ws, "M13"),\n            _cell(ws, "M12"),\n        ),\n    )\n\n    _set(\n        ws,\n        "M22",\n        safe_percent(\n            _cell(ws, "M21"),\n            _cell(ws, "M13"),\n        ),\n    )\n\n    _set(\n        ws,\n        "M28",\n        safe_percent(\n            _cell(ws, "M27"),\n            _cell(ws, "M26"),\n        ),\n    )\n\n\ndef _apply_old_te(\n    ws: Any,\n) -> None:\n    # Template master cũ: tỷ lệ huy động E17:L17.\n    for col in (\n        "E", "F", "G", "H",\n        "I", "J", "K",\n    ):\n        _set(\n            ws,\n            f"{col}17",\n            safe_percent(\n                _cell(ws, f"{col}14"),\n                _cell(ws, f"{col}13"),\n            ),\n        )\n\n        _set(\n            ws,\n            f"{col}28",\n            safe_percent(\n                _cell(ws, f"{col}27"),\n                _cell(ws, f"{col}26"),\n            ),\n        )\n\n    _set(\n        ws,\n        "L17",\n        safe_percent(\n            _cell(ws, "L14"),\n            _cell(ws, "L13"),\n        ),\n    )\n\n    _set(\n        ws,\n        "L28",\n        safe_percent(\n            _cell(ws, "L27"),\n            _cell(ws, "L26"),\n        ),\n    )\n\n\ndef _apply_tc_dk(\n    ws: Any,\n) -> None:\n    # Bảng bắt đầu dữ liệu từ dòng 8; chạy rộng để hỗ trợ\n    # toàn tỉnh + nhiều xã/phường.\n    for row in range(\n        8,\n        int(ws.max_row) + 1,\n    ):\n        h = safe_number(\n            _cell(ws, f"H{row}")\n        )\n        i = safe_number(\n            _cell(ws, f"I{row}")\n        )\n\n        if h is not None or i is not None:\n            _set(\n                ws,\n                f"G{row}",\n                (h or 0.0) + (i or 0.0),\n            )\n\n        _set(\n            ws,\n            f"L{row}",\n            safe_percent(\n                _cell(ws, f"K{row}"),\n                _cell(ws, f"J{row}"),\n            ),\n        )\n\n        _set(\n            ws,\n            f"N{row}",\n            safe_percent(\n                _cell(ws, f"M{row}"),\n                _cell(ws, f"K{row}"),\n            ),\n        )\n\n        _set(\n            ws,\n            f"R{row}",\n            safe_percent(\n                _cell(ws, f"Q{row}"),\n                _cell(ws, f"P{row}"),\n            ),\n        )\n\n\ndef _apply_gv(\n    ws: Any,\n) -> None:\n    for row in range(\n        8,\n        int(ws.max_row) + 1,\n    ):\n        _set(\n            ws,\n            f"N{row}",\n            safe_ratio(\n                _cell(ws, f"K{row}"),\n                _cell(ws, f"J{row}"),\n            ),\n        )\n\n        qualified = safe_number(\n            _cell(ws, f"O{row}")\n        )\n        above = safe_number(\n            _cell(ws, f"P{row}")\n        )\n\n        numerator = None\n\n        if (\n            qualified is not None\n            or above is not None\n        ):\n            numerator = (\n                (qualified or 0.0)\n                + (above or 0.0)\n            )\n\n        _set(\n            ws,\n            f"Q{row}",\n            safe_percent(\n                numerator,\n                _cell(ws, f"K{row}"),\n            ),\n        )\n\n        _set(\n            ws,\n            f"S{row}",\n            safe_percent(\n                _cell(ws, f"R{row}"),\n                _cell(ws, f"K{row}"),\n            ),\n        )\n\n\ndef _apply_csvc(\n    ws: Any,\n) -> None:\n    for row in range(\n        9,\n        int(ws.max_row) + 1,\n    ):\n        _set(\n            ws,\n            f"L{row}",\n            safe_ratio(\n                _cell(ws, f"K{row}"),\n                _cell(ws, f"H{row}"),\n            ),\n        )\n\n\ndef _apply_old_gv(\n    ws: Any,\n) -> None:\n    # Template master cũ MN-01 GV.\n    for row in range(\n        8,\n        int(ws.max_row) + 1,\n    ):\n        _set(\n            ws,\n            f"N{row}",\n            safe_ratio(\n                _cell(ws, f"K{row}"),\n                _cell(ws, f"J{row}"),\n            ),\n        )\n\n        standard = safe_number(\n            _cell(ws, f"O{row}")\n        )\n        above = safe_number(\n            _cell(ws, f"P{row}")\n        )\n\n        total_standard = None\n\n        if (\n            standard is not None\n            or above is not None\n        ):\n            total_standard = (\n                (standard or 0.0)\n                + (above or 0.0)\n            )\n\n        _set(\n            ws,\n            f"Q{row}",\n            safe_percent(\n                total_standard,\n                _cell(ws, f"K{row}"),\n            ),\n        )\n\n        _set(\n            ws,\n            f"S{row}",\n            safe_percent(\n                _cell(ws, f"R{row}"),\n                _cell(ws, f"K{row}"),\n            ),\n        )\n\n\ndef _apply_finance(\n    ws: Any,\n) -> None:\n    # Chỉ tính đúng công thức /5 khi đủ 5 năm số liệu.\n    for row in (\n        13,\n        14,\n    ):\n        values = [\n            safe_number(\n                _cell(\n                    ws,\n                    f"{col}{row}",\n                )\n            )\n            for col in (\n                "E", "F", "G", "H", "I",\n            )\n        ]\n\n        if all(\n            value is not None\n            for value in values\n        ):\n            _set(\n                ws,\n                f"D{row}",\n                round(\n                    sum(values) / 5.0,\n                    2,\n                ),\n            )\n        else:\n            _set(\n                ws,\n                f"D{row}",\n                None,\n            )\n\n\ndef apply_formula_contract(\n    workbook: Any,\n) -> None:\n    """\n    Post-processing công thức dùng cho cả:\n    - biểu mới người dùng vừa cung cấp;\n    - template master cũ;\n    - các file xuất chia biểu.\n\n    Hàm chỉ tính từ ô nguồn đã được builder điền.\n    Không tạo số liệu nguồn giả.\n    """\n    ws = _sheet(\n        workbook,\n        "Thống kê trẻ em từ 0 đến 5 tuổi",\n    )\n    if ws is not None:\n        _apply_new_te(ws)\n\n    ws = _sheet(\n        workbook,\n        "MN-01 TE",\n    )\n    if ws is not None:\n        _apply_old_te(ws)\n\n    ws = _sheet(\n        workbook,\n        "TK dat chuan",\n        "MN-02",\n    )\n    if ws is not None and ws.title == "TK dat chuan":\n        _apply_tc_dk(ws)\n\n    ws = _sheet(\n        workbook,\n        "GV",\n    )\n    if ws is not None:\n        _apply_gv(ws)\n\n    ws = _sheet(\n        workbook,\n        "MN-01 GV",\n    )\n    if ws is not None:\n        _apply_old_gv(ws)\n\n    ws = _sheet(\n        workbook,\n        "CSVC",\n    )\n    if ws is not None:\n        _apply_csvc(ws)\n\n    ws = _sheet(\n        workbook,\n        "Báo cáo tài chính",\n    )\n    if ws is not None:\n        _apply_finance(ws)\n'

