def read_text(
    path: Path,
) -> str:
    return path.read_text(
        encoding="utf-8-sig",
        errors="strict",
    )


def write_text(
    path: Path,
    value: str,
) -> None:
    path.parent.mkdir(
        parents=True,
        exist_ok=True,
    )

    path.write_text(
        value,
        encoding="utf-8",
    )


def function_node(
    source: str,
    name: str,
):
    tree = ast.parse(
        source
    )

    matches = [
        node
        for node in tree.body
        if isinstance(
            node,
            (
                ast.FunctionDef,
                ast.AsyncFunctionDef,
            ),
        )
        and node.name == name
    ]

    if len(matches) != 1:
        raise RuntimeError(
            f"Phải tìm thấy đúng 1 hàm {name}; "
            f"hiện có {len(matches)}."
        )

    return matches[0]


def function_span(
    source: str,
    name: str,
) -> tuple[int, int]:
    node = function_node(
        source,
        name,
    )

    lines = source.splitlines(
        keepends=True
    )

    offsets = [0]

    for line in lines:
        offsets.append(
            offsets[-1]
            + len(line)
        )

    return (
        offsets[
            int(node.lineno) - 1
        ],
        offsets[
            int(node.end_lineno)
        ],
    )


def get_function(
    source: str,
    name: str,
) -> str:
    start, end = function_span(
        source,
        name,
    )

    return source[
        start:end
    ]


def replace_function(
    source: str,
    name: str,
    replacement: str,
) -> str:
    start, end = function_span(
        source,
        name,
    )

    result = (
        source[:start]
        + replacement.rstrip()
        + "\n\n"
        + source[end:].lstrip("\n")
    )

    ast.parse(
        result
    )

    return result


def ast_return_name(
    source: str,
    function_name: str,
) -> str | None:
    node = function_node(
        source,
        function_name,
    )

    returns = [
        item
        for item in ast.walk(node)
        if isinstance(
            item,
            ast.Return,
        )
        and isinstance(
            item.value,
            ast.Name,
        )
    ]

    values = {
        item.value.id
        for item in returns
    }

    if len(values) == 1:
        return next(
            iter(values)
        )

    return None


def db_state() -> dict:
    if not DB.exists():
        return {
            "exists": False,
        }

    conn = sqlite3.connect(
        str(DB)
    )

    try:
        integrity = str(
            conn.execute(
                "PRAGMA integrity_check"
            ).fetchone()[0]
        )

        fk = len(
            conn.execute(
                "PRAGMA foreign_key_check"
            ).fetchall()
        )

        columns = {
            str(row[1])
            for row in conn.execute(
                "PRAGMA table_info("
                "survey_person_year_records"
                ")"
            ).fetchall()
        }

        count = int(
            conn.execute(
                "SELECT COUNT(*) "
                "FROM survey_person_year_records"
            ).fetchone()[0]
        )

        tables = {
            str(row[0])
            for row in conn.execute(
                "SELECT name FROM sqlite_master "
                "WHERE type='table'"
            ).fetchall()
        }

        return {
            "exists": True,
            "integrity": integrity,
            "fk": fk,
            "columns": sorted(
                columns
            ),
            "count": count,
            "tables": sorted(
                tables
            ),
        }

    finally:
        conn.close()


def backup_db() -> None:
    if not DB.exists():
        return

    src = sqlite3.connect(
        str(DB)
    )

    dst = sqlite3.connect(
        str(
            BACKUP
            / "phocap.db"
        )
    )

    try:
        src.backup(
            dst
        )
    finally:
        dst.close()
        src.close()


def restore_sources() -> None:
    mapping = (
        (
            "mn_official_reports.py",
            OFFICIAL,
        ),
        (
            "pcgdmn_template_report.py",
            MASTER,
        ),
        (
            "pcgd_mn_report_builders_v1.py",
            LEGACY,
        ),
    )

    for name, target in mapping:
        saved = (
            BACKUP / name
        )

        if saved.exists():
            shutil.copy2(
                saved,
                target,
            )


def clear_cache() -> None:
    for cache in APP.rglob(
        "__pycache__"
    ):
        if cache.is_dir():
            shutil.rmtree(
                cache,
                ignore_errors=True,
            )


def install_reference() -> None:
    data = gzip.decompress(
        base64.b64decode(
            REFERENCE_GZIP_B64
        )
    )

    digest = hashlib.sha256(
        data
    ).hexdigest()

    if digest != REFERENCE_SHA256:
        raise RuntimeError(
            "SHA256 biểu Mầm non nhúng trong "
            "bộ cài không đúng."
        )

    REFERENCE.parent.mkdir(
        parents=True,
        exist_ok=True,
    )

    REFERENCE.write_bytes(
        data
    )

    check = hashlib.sha256(
        REFERENCE.read_bytes()
    ).hexdigest()

    if check != REFERENCE_SHA256:
        raise RuntimeError(
            "Kiểm tra file tham chiếu sau ghi "
            "không đạt."
        )


def patch_official(
    source: str,
) -> tuple[str, list[str]]:
    notes = []

    required = (
        "_query_te_people",
        "_te_metrics",
        "_fill_te_workbook",
    )

    for name in required:
        function_node(
            source,
            name,
        )

    query = get_function(
        source,
        "_query_te_people",
    )

    for field in (
        "disability_can_learn",
        "disability_access_education",
    ):
        token = f"spr.{field}"

        if token in query:
            continue

        anchors = (
            "            spr.completed_preschool_5,\n",
            "            spr.prepared_vietnamese,\n",
            "            spr.disability_status,\n",
        )

        used = False

        for anchor in anchors:
            if anchor in query:
                query = query.replace(
                    anchor,
                    anchor
                    + f"            spr.{field},\n",
                    1,
                )

                used = True
                break

        if not used:
            raise RuntimeError(
                "Không tìm thấy anchor an toàn để "
                f"thêm spr.{field} vào _query_te_people."
            )

    source = replace_function(
        source,
        "_query_te_people",
        query,
    )

    metrics = get_function(
        source,
        "_te_metrics",
    )

    # Thêm metric nguồn khuyết tật nếu chưa có.
    if '"disabled_capable"' not in metrics:
        metric_anchors = (
            '"two_sessions_known",',
            '"two_sessions",',
            '"completed5",',
        )

        used = False

        for anchor in metric_anchors:
            if anchor in metrics:
                metrics = metrics.replace(
                    anchor,
                    anchor
                    + ' "disabled_capable", '
                    '"disabled_access_v246",',
                    1,
                )

                used = True
                break

        if not used:
            raise RuntimeError(
                "Không tìm thấy danh sách metric "
                "trong _te_metrics."
            )

    logic_marker = (
        "# === BAI_13B_11_15_2_4_6_"
        "DISABILITY_METRICS ==="
    )

    if logic_marker not in metrics:
        anchor = "        if attending:\n"

        if anchor not in metrics:
            raise RuntimeError(
                "Không tìm thấy `if attending:` "
                "trong _te_metrics."
            )

        logic = (
            "        "
            + logic_marker
            + "\n"
            + "        _v246_can_raw = "
            "_as_bool(row.get("
            '"disability_can_learn"))\n'
            + "        _v246_access_raw = "
            "_as_bool(row.get("
            '"disability_access_education"))\n'
            + "        _v246_can = (\n"
            + "            _v246_can_raw is True\n"
            + "            or (\n"
            + "                _v246_can_raw is None\n"
            + "                and _v246_access_raw is True\n"
            + "            )\n"
            + "        )\n"
            + "        if _v246_can:\n"
            + '            metrics["disabled_capable"][age] += 1\n'
            + "            if _v246_access_raw is True:\n"
            + '                metrics["disabled_access_v246"][age] += 1\n'
            + "\n"
        )

        metrics = metrics.replace(
            anchor,
            logic + anchor,
            1,
        )

    source = replace_function(
        source,
        "_te_metrics",
        metrics,
    )

    fill = get_function(
        source,
        "_fill_te_workbook",
    )

    fill_marker = (
        "# === BAI_13B_11_15_2_4_6_"
        "OFFICIAL_FILL ==="
    )

    if fill_marker not in fill:
        addition = (
            "\n"
            + "    "
            + fill_marker
            + "\n"
            + "    _v246_capable = metrics.get("
            '"disabled_capable", {})\n'
            + "    _v246_access = metrics.get("
            '"disabled_access_v246", {})\n'
            + "    _v246_age_cols = {"
            "0:'F',1:'G',2:'H',3:'I',"
            "4:'J',5:'K',6:'L'}\n"
            + "    for _v246_age, _v246_col in "
            "_v246_age_cols.items():\n"
            + "        _v246_den = int("
            "_v246_capable.get(_v246_age, 0) or 0)\n"
            + "        _v246_num = int("
            "_v246_access.get(_v246_age, 0) or 0)\n"
            + "        ws[f'{_v246_col}10'] = "
            "_v246_den if _v246_den > 0 else None\n"
            + "        ws[f'{_v246_col}11'] = "
            "_v246_num if _v246_den > 0 else None\n"
            + "    ws['M10'] = sum("
            "int(_v246_capable.get(a,0) or 0) "
            "for a in range(6)) or None\n"
            + "    ws['M11'] = sum("
            "int(_v246_access.get(a,0) or 0) "
            "for a in range(6)) "
            "if ws['M10'].value else None\n"
            + "    from app.services.mn_report_v246 "
            "import apply_formula_contract\n"
            + "    apply_formula_contract(wb)\n"
        )

        fill = fill.rstrip() + addition + "\n"

    source = replace_function(
        source,
        "_fill_te_workbook",
        fill,
    )

    if MARK_OFFICIAL not in source:
        start, _end = function_span(
            source,
            "_query_te_people",
        )

        source = (
            source[:start]
            + MARK_OFFICIAL
            + "\n"
            + source[start:]
        )

    ast.parse(
        source
    )

    notes.append(
        "MN-01-TE: đã nối "
        "disability_can_learn / "
        "disability_access_education."
    )

    notes.append(
        "MN-01-TE: tỷ lệ được post-process "
        "bằng Python theo biểu mới."
    )

    return source, notes


def patch_master(
    source: str,
) -> tuple[str, list[str]]:
    notes = []

    function_node(
        source,
        "build_template_workbook",
    )

    fn = get_function(
        source,
        "build_template_workbook",
    )

    if (
        "apply_formula_contract("
        not in fn
    ):
        returned = ast_return_name(
            source,
            "build_template_workbook",
        )

        if not returned:
            raise RuntimeError(
                "Không xác định được biến workbook "
                "được return bởi build_template_workbook."
            )

        return_line = (
            f"    return {returned}\n"
        )

        if return_line not in fn:
            return_line = (
                f"    return {returned}"
            )

        if return_line not in fn:
            raise RuntimeError(
                "Không tìm thấy dòng return workbook "
                "trong build_template_workbook."
            )

        call = (
            "    "
            + MARK_MASTER
            + "\n"
            + "    from app.services.mn_report_v246 "
            "import apply_formula_contract\n"
            + f"    apply_formula_contract({returned})\n"
        )

        fn = fn.replace(
            return_line,
            call + return_line,
            1,
        )

        source = replace_function(
            source,
            "build_template_workbook",
            fn,
        )

        notes.append(
            "Bộ 7 sheet: đã nối post-processing "
            "công thức từ biểu người dùng gửi."
        )
    else:
        notes.append(
            "Bộ 7 sheet: post-processing đã tồn tại."
        )

    ast.parse(
        source
    )

    return source, notes


def patch_legacy(
    source: str,
) -> tuple[str, list[str]]:
    notes = []

    function_node(
        source,
        "export_mn_report",
    )

    fn = get_function(
        source,
        "export_mn_report",
    )

    if MARK_LEGACY not in fn:
        save_pos = fn.find(
            "workbook.save("
        )

        if save_pos < 0:
            raise RuntimeError(
                "Không tìm thấy workbook.save trong "
                "export_mn_report."
            )

        line_start = (
            fn.rfind(
                "\n",
                0,
                save_pos,
            )
            + 1
        )

        indent = fn[
            line_start:save_pos
        ]

        call = (
            indent
            + MARK_LEGACY
            + "\n"
            + indent
            + "from app.services.mn_report_v246 "
            "import apply_formula_contract\n"
            + indent
            + "apply_formula_contract(workbook)\n"
        )

        fn = (
            fn[:line_start]
            + call
            + fn[line_start:]
        )

        source = replace_function(
            source,
            "export_mn_report",
            fn,
        )

        notes.append(
            "Builder Mầm non cũ: đã nối "
            "post-processing công thức."
        )
    else:
        notes.append(
            "Builder Mầm non cũ: đã có post-processing."
        )

    ast.parse(
        source
    )

    return source, notes


def verify_source(
    official: str,
    master: str,
    legacy: str,
) -> None:
    ast.parse(
        official
    )

    ast.parse(
        master
    )

    ast.parse(
        legacy
    )

    checks = (
        (
            official,
            (
                MARK_OFFICIAL,
                "spr.disability_can_learn",
                "spr.disability_access_education",
                '"disabled_capable"',
                '"disabled_access_v246"',
                "apply_formula_contract(wb)",
            ),
        ),
        (
            master,
            (
                MARK_MASTER,
                "apply_formula_contract(",
            ),
        ),
        (
            legacy,
            (
                MARK_LEGACY,
                "apply_formula_contract(workbook)",
            ),
        ),
    )

    for text, tokens in checks:
        for token in tokens:
            if token not in text:
                raise RuntimeError(
                    "Verifier sau patch thiếu: "
                    + token
                )


